package com.payslipmax.pdfparser.guide.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * The Claim Guide bundle, generated by `docs/Plan/rule_cards/tools/bundle.py` from the authored rule cards.
 * Plain strings and lists only (no polymorphic or sealed serialized types) so the release build needs no
 * Guide keep rule (`scripts/check_r8_guide.py` proves the models survive R8). Area, case and facet ids stay
 * strings, so a new area or chapter is a data-only change.
 */
@Serializable
data class GuideBundle(
    val version: Int,
    val generated: String = "",
    @SerialName("rates_as_of") val ratesAsOf: String,
    val limits: GuideLimits,
    val nav: List<GuideArea>,
    /** Facet key (for example "Q") to its label (for example "Who qualifies"). Content, not UI copy. */
    val facets: Map<String, String>,
    val cards: List<GuideCard>,
    /** The rupee figures behind the "your figure" line (phase E6); null in a bundle that carries none. */
    val figures: GuideFigures? = null,
    /** The TA/DA pre-claim worksheet content (plan 22, P3); null in a bundle that carries none. */
    val preclaim: GuidePreClaim? = null,
    /** Hand-written change-log entries (the newest 12, newest first); empty in a bundle that carries none. */
    val changes: List<GuideChange> = emptyList(),
)

/** One dated entry of the change log (`authoring/changes.txt`): what changed in the Guide on [date] (YYYY-MM-DD). */
@Serializable
data class GuideChange(
    val date: String,
    val items: List<GuideChangeItem>,
)

/** One line of a change-log entry, with the cards it concerns (may be empty). Content, not UI copy. */
@Serializable
data class GuideChangeItem(
    val text: String,
    val cards: List<String> = emptyList(),
)

/** Word and bullet limits the compiler enforced; the validator rechecks them on every load. */
@Serializable
data class GuideLimits(
    val title: Int,
    val answer: Int,
    val bullets: Int,
    @SerialName("bullet_words") val bulletWords: Int,
    val visible: Int,
    val details: Int,
)

@Serializable
data class GuideArea(
    val id: String,
    val title: String,
    val cases: List<GuideCase>,
)

/** A case tile. [cards] are the cards homed here, in display order; [also] are cards homed elsewhere. */
@Serializable
data class GuideCase(
    val id: String,
    val title: String,
    val sub: String = "",
    val cards: List<String>,
    val also: List<String> = emptyList(),
)

@Serializable
data class GuideCard(
    val id: String,
    val title: String,
    val answer: String,
    val key: List<String>,
    val attach: List<String> = emptyList(),
    val watch: List<String> = emptyList(),
    val cite: String = "",
    val details: String = "",
    val chips: List<String> = emptyList(),
    /** Marks a card that has a "your figure" line (for example "level:food_rate"); `figures.json` must hold its figure. */
    val personal: String = "",
    val facet: String,
    /** Id of the one case this card is homed in. */
    val nav: String,
    /** True when the card carries an open review point: shown as the "Unverified point" chip. */
    val unverified: Boolean = false,
    /** First 8 hex characters of the SHA-256 of the card's shipped text; changes when the words a user reads change. */
    val rev: String = "",
    /** Date (YYYY-MM-DD) the rule applies from; empty when the card is undated. */
    val effective: String = "",
    /** Id of the card that replaced this one from [until]; empty for a current card. A replaced card is homed in no case. */
    @SerialName("replaced_by") val replacedBy: String = "",
    /** Date (YYYY-MM-DD) this rule stopped applying, the successor's effective date; empty for a current card. */
    val until: String = "",
) {
    /** True once a newer dated rule replaced this card; it stays in the data for the "earlier rule" link and old claims. */
    val isReplaced: Boolean get() = replacedBy.isNotBlank()

    /** Typed chips; a chip this app version does not know maps to [GuideChip.UNKNOWN], which the UI ignores. */
    val trustChips: List<GuideChip> get() = chips.map(GuideChip::fromKey)

    /** The "No official source" chip. Owner rule (2026-10-07): exactly the cards with no cite. */
    val hasNoOfficialSource: Boolean get() = cite.isBlank()
}

enum class GuideChip {
    RATES,
    AMENDED,
    GUIDANCE,
    UNKNOWN,
    ;

    companion object {
        fun fromKey(key: String): GuideChip = entries.firstOrNull { it != UNKNOWN && it.name == key } ?: UNKNOWN
    }
}

/**
 * The owner-approved rates behind the "your figure" line, generated from `docs/Plan/rule_cards/figures.json`. No rupee
 * figure is written in Kotlin: the resolver reads these. Every field has a default or is optional so a newer bundle
 * that adds modes or fields still loads; a mode this version does not know simply shows no line.
 */
@Serializable
data class GuideFigures(
    @SerialName("da_step") val daStep: GuideDaStep,
    /** Figure key (for example "food_rate") to its data. */
    val figures: Map<String, GuideFigure>,
)

/**
 * A rate rises by [increasePercent] each time DA rises by [perDaPercent] (MoD 15-09-2017: 25% per 50%). [firstStepEffectiveFrom]
 * (YYYY-MM-DD, empty if not shipped) is the day the first step, at DA 50%, reaches the lump sums (the owner's decision, 2026-10-11).
 */
@Serializable
data class GuideDaStep(
    @SerialName("per_da_percent") val perDaPercent: Int,
    @SerialName("increase_percent") val increasePercent: Int,
    @SerialName("first_step_effective_from") val firstStepEffectiveFrom: String = "",
)

/**
 * One personal figure. [mode] is `da_step` (band base raised by the DA step), `percent_of_basic`, `plus_da` (band base
 * plus DA on it), `rate_table` (a percent of basic by city class and DA step) or `rate_by_state` (rupees per km in [rates],
 * keyed by state). [assumption] is content, like card text. A figure either belongs to a rule [card] (its "your figure" line)
 * or has [use] `preclaim` and no card: it feeds the TA/DA pre-claim worksheet and never reaches a card.
 */
@Serializable
data class GuideFigure(
    val card: String = "",
    val use: String = "",
    val mode: String,
    val assumption: String = "",
    @SerialName("effective_from") val effectiveFrom: String = "",
    val percent: Int = 0,
    val bands: List<GuideFigureBand> = emptyList(),
    val classes: Map<String, List<GuideRateStep>> = emptyMap(),
    val rates: Map<String, Int> = emptyMap(),
)

/**
 * Pay levels (labels as printed, for example "12A") sharing one [base]; [cityClass] is `HIGHER`, `OTHER` or `ANY`. A band the
 * rules cap without a rupee figure has no [base] (0) and carries a [limit] text instead; never both.
 */
@Serializable
data class GuideFigureBand(
    val levels: List<String>,
    @SerialName("city_class") val cityClass: String = "ANY",
    val base: Int = 0,
    val limit: String = "",
)

/** From [fromDaPercent] upwards a city class gets [percent] of basic pay, in force from [effectiveFrom]. */
@Serializable
data class GuideRateStep(
    @SerialName("from_da_percent") val fromDaPercent: Int,
    val percent: Int,
    @SerialName("effective_from") val effectiveFrom: String,
)

/**
 * The TA/DA pre-claim worksheet as data, generated from `docs/Plan/rule_cards/preclaim.json`: per move type the portal's fields in
 * the portal's order, the documents to scan, and the dropdown options (one of them the LTC rule picker). All text is content, like
 * card text, never UI copy. Kinds and sources stay strings (as [GuideFigure.mode] does) so the models need no keep rule.
 */
@Serializable
data class GuidePreClaim(
    val limits: GuidePreClaimLimits,
    val upload: GuideUploadRule,
    /** Option-group id (for example "mode_of_journey") to its options. */
    val options: Map<String, GuideOptionGroup>,
    /** Move type (`PD`, `TD`, `LTC`) to its worksheet. */
    val moves: Map<String, GuidePreClaimMove>,
)

/** Character limits `preclaim.py` enforced and the validator rechecks: the one home for them, so Kotlin holds no second copy. */
@Serializable
data class GuidePreClaimLimits(
    val label: Int,
    val hint: Int,
    @SerialName("text_chars") val textChars: Int,
)

/** The portal takes [files] scanned [format] file, more than [moreThanKb] KB and less than [lessThanMb] MB. */
@Serializable
data class GuideUploadRule(
    val files: Int,
    @SerialName("more_than_kb") val moreThanKb: Int,
    @SerialName("less_than_mb") val lessThanMb: Int,
    val format: String,
)

/** A dropdown. When [cardLinked] every option names a rule card (the LTC rule picker); otherwise none does. */
@Serializable
data class GuideOptionGroup(
    @SerialName("card_linked") val cardLinked: Boolean = false,
    val options: List<GuideOption>,
)

@Serializable
data class GuideOption(
    val id: String,
    val label: String,
    /** One line on when to choose this option; required for a card-linked group. */
    @SerialName("use_when") val useWhen: String = "",
    val card: String = "",
)

/** One move type's worksheet: [fields] in the portal's order, the scanned [documents], and short [notes]. */
@Serializable
data class GuidePreClaimMove(
    val title: String,
    val fields: List<GuidePreClaimField>,
    val documents: List<GuidePreClaimDocument>,
    val notes: List<String> = emptyList(),
)

/**
 * One portal field. [kind] is the input the app shows (`text`, `date`, `number`, `amount`, `tick`, `choice`) and [source] says who fills
 * it (`portal_filled`, `officer_types`, `app_suggests`). A [maxChars] limit applies to text; a `choice` names its group in [options].
 * An [unverified] field was not confirmed on the portal and its [hint] says what.
 */
@Serializable
data class GuidePreClaimField(
    val id: String,
    val label: String,
    val kind: String,
    val source: String,
    @SerialName("max_chars") val maxChars: Int = 0,
    val options: String = "",
    val hint: String = "",
    val unverified: Boolean = false,
)

/** A document to scan; [whenNeeded] (JSON key `when`) says when it applies, empty for always. */
@Serializable
data class GuidePreClaimDocument(
    val id: String,
    val label: String,
    @SerialName("when") val whenNeeded: String = "",
)
